create table if not exists campaigns (id bigserial primary key, organization_id uuid not null references organizations(id), name text not null, channel text not null default 'other' check (channel in ('email','whatsapp','ads','social','other')), status text not null default 'draft' check (status in ('draft','active','paused','done')), budget numeric(14,2) not null default 0 check (budget >= 0), starts_on date, ends_on date, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create index if not exists campaigns_organization_id_idx on campaigns(organization_id);
